CASE ssMethodType OF
    SS_INITIALIZE: 
        temporalCounter_i1(timerAction := 1, maxTime := 0);
        is_active_c45_libCM := 0;
        is_c45_libCM := ChiefMaster0_IN_NO_ACTIVE_CHILD_g;
        Out := FALSE;
    SS_OUTPUT: 
        IF is_active_c45_libCM = 0 THEN 
            is_active_c45_libCM := 1;
            is_c45_libCM := ChiefMaster0_IN_Default_o;
            temporalCounter_i1(timerAction := 1, maxTime := 0);
            Out := FALSE;
        ELSE 
            CASE is_c45_libCM OF
                ChiefMaster0_IN_Default_o: 
                    IF  NOT KL15_CM_Reset THEN 
                        temporalCounter_i1(timerAction := 2, maxTime := 100);
                        IF temporalCounter_i1.done THEN 
                            is_c45_libCM := ChiefMaster0_IN_hold_n;
                            Out := In;
                        ELSE 
                            Out := FALSE;
                        END_IF;
                    ELSE 
                        Out := FALSE;
                    END_IF;
                ELSE
                    Out := In;
            END_CASE;
        END_IF;
END_CASE;

CASE ssMethodType OF
    SS_INITIALIZE: 
        is_active_c9_ChiefMaster0 := 0;
        is_c9_ChiefMaster0 := ChiefMaster0_IN_NO_ACTIVE_CHILD_i3;
        BattSelect := 0.0;
    SS_OUTPUT: 
        IF is_active_c9_ChiefMaster0 = 0 THEN 
            is_active_c9_ChiefMaster0 := 1;
            is_c9_ChiefMaster0 := ChiefMaster0_IN_Default_at;
            BattSelect := 0.0;
        ELSE 
            CASE is_c9_ChiefMaster0 OF
                ChiefMaster0_IN_Actia: 
                    IF  NOT BattAvailable_Actia THEN 
                        is_c9_ChiefMaster0 := ChiefMaster0_IN_Default_at;
                        BattSelect := 0.0;
                    ELSE 
                        BattSelect := 1.0;
                    END_IF;
                ChiefMaster0_IN_Default_at: 
                    IF BattAvailable_Actia AND ( NOT BattAvailable_LiBa) THEN 
                        is_c9_ChiefMaster0 := ChiefMaster0_IN_Actia;
                        BattSelect := 1.0;
