                        IF ( NOT BattAvailable_Actia) AND BattAvailable_LiBa THEN 
                            is_c9_ChiefMaster0 := ChiefMaster0_IN_LiBa;
                            BattSelect := 2.0;
                        ELSE 
                            BattSelect := 0.0;
