CASE ssMethodType OF
    SS_INITIALIZE: 
        temporalCounter_i1(timerAction := 1, maxTime := 0);
        is_active_c63_ChiefMaster0 := 0;
        is_c63_ChiefMaster0 := ChiefMaster0_IN_NO_ACTIVE_CHILD_gd;
        IMD_OK_i := FALSE;
    SS_OUTPUT: 
        Req_IMD_prev := Req_IMD_start;
        Req_IMD_start := Req_IMD;
        IF is_active_c63_ChiefMaster0 = 0 THEN 
            Req_IMD_prev := Req_IMD;
            is_active_c63_ChiefMaster0 := 1;
            is_c63_ChiefMaster0 := ChiefMaster0_IN_Default_in;
            IMD_OK_i := FALSE;
        ELSE 
            CASE is_c63_ChiefMaster0 OF
                ChiefMaster0_IN_Default_in: 
                    IF IP_boBMS_InsulationReadyOK THEN 
                        is_c63_ChiefMaster0 := ChiefMaster0_IN_Hold3;
                        temporalCounter_i1(timerAction := 1, maxTime := 0);
                        IMD_OK_i := FALSE;
                    ELSE 
                        IMD_OK_i := FALSE;
                    END_IF;
                ChiefMaster0_IN_Hold_m: 
                    IF  NOT Req_IMD THEN 
                        is_c63_ChiefMaster0 := ChiefMaster0_IN_Hold2;
                        IMD_OK_i := TRUE;
                    ELSE 
                        IMD_OK_i := TRUE;
                    END_IF;
                ChiefMaster0_IN_Hold2: 
                    IF (Req_IMD_prev <> Req_IMD_start) AND ( NOT Req_IMD_prev) THEN 
                        is_c63_ChiefMaster0 := ChiefMaster0_IN_Default_in;
                        IMD_OK_i := FALSE;
                    ELSE 
                        IMD_OK_i := TRUE;
                    END_IF;
                ELSE
                    temporalCounter_i1(timerAction := 2, maxTime := USINT_TO_DINT(IT_u8IMD_DelayTime_s_g) * 1000);
                    IF temporalCounter_i1.done THEN 
                        IF IP_boBMS_InsulationReadyOK THEN 
                            is_c63_ChiefMaster0 := ChiefMaster0_IN_Hold_m;
                            IMD_OK_i := TRUE;
                        ELSE 
                            IMD_OK_i := FALSE;
                        END_IF;
                    ELSE 
                        IMD_OK_i := FALSE;
                    END_IF;
            END_CASE;
        END_IF;
END_CASE;

