        IF is_active_c1_libCM = 0 THEN 
            is_active_c1_libCM := 1;
            is_c1_libCM := ChiefMaster0_IN_Default_l;
            REQ_HV_ON := 0.0;
            ContactorState := 1.0;
        ELSE 
            temp2 := FALSE;
            temp3 := FALSE;
            temp4 := FALSE;
            temp5 := FALSE;
            CASE is_c1_libCM OF
                ChiefMaster0_IN_CONTACTOR_OFF: 
                    IF ((( NOT InsulationReadyOK) OR SDError_BB) OR Software_Reset_KL15_BB) OR KL15_CM_disable THEN 
                        is_c1_libCM := ChiefMaster0_IN_Default_l;
                        REQ_HV_ON := 0.0;
                        ContactorState := 1.0;
                    ELSE 
                        temporalCounter_i1(timerAction := 2, maxTime := 2000);
                        IF temporalCounter_i1.done THEN 
                            IF ((IMD_Active_BB1 AND ( NOT IMD_Active_BB2)) AND ( NOT IMD_Active_BB3)) AND ( NOT MainHV_PlusMinus_Status) THEN 
                                temp3 := TRUE;
                            ELSE 
                                temp5 := TRUE;
                            END_IF;
                        ELSE 
                            temp5 := TRUE;
                        END_IF;
                    END_IF;
                ChiefMaster0_IN_CONTACTOR_ON: 
                    tmp :=  NOT HV_REL_ON_BB1;
                    IF ((KL15_CM_disable OR System_SD) OR SDError_BB) AND (MainHV_SD_OK OR tmp) THEN 
                        is_c1_libCM := ChiefMaster0_IN_hold_b;
                        temporalCounter_i1(timerAction := 1, maxTime := 0);
                    ELSE 
                        temp1 := HV_REL_ON_BB2 OR HV_REL_ON_BB3;
                        IF (SDError_BB AND temp1) AND (SafeToSD OR tmp) THEN 
                            temp4 := TRUE;
                        ELSE 
                            IF temp1 AND REQ_HV_Open THEN 
                                temp4 := TRUE;
                            ELSE 
                                REQ_HV_ON := 1.0;
                                ContactorState := 3.0;
                            END_IF;
                        END_IF;
                    END_IF;
                ChiefMaster0_IN_Default_l: 
                    IF (((( NOT IP_boChargeStop_Pressed) AND ( NOT KL15_CM_disable)) AND InsulationReadyOK) AND ( NOT SDError_BB)) AND ( NOT System_SD) THEN 
                        is_c1_libCM := ChiefMaster0_IN_CONTACTOR_OFF;
                        temporalCounter_i1(timerAction := 1, maxTime := 0);
                        temporalCounter_i2(timerAction := 1, maxTime := 0);
                        REQ_HV_ON := 0.0;
                        ContactorState := 2.0;
                    ELSE 
                        REQ_HV_ON := 0.0;
                        ContactorState := 1.0;
                    END_IF;
                ELSE
                    temporalCounter_i1(timerAction := 2, maxTime := 2000);
                    IF temporalCounter_i1.done THEN 
                        is_c1_libCM := ChiefMaster0_IN_Default_l;
                        REQ_HV_ON := 0.0;
                        ContactorState := 1.0;
                    END_IF;
            END_CASE;
            IF temp5 THEN 
                temporalCounter_i2(timerAction := 2, maxTime := 2000);
                IF temporalCounter_i2.done THEN 
                    IF ((( NOT IMD_Active_BB1) AND MainHV_PlusMinus_Status) AND ((IMD_Active_BB2 OR IMD_Active_BB3) OR ( NOT IsolationMeasurementRequest))) AND SafeToCloseHV_mb THEN 
                        temp3 := TRUE;
                    ELSE 
                        temp2 := TRUE;
                    END_IF;
                ELSE 
                    temp2 := TRUE;
                END_IF;
            END_IF;
            IF temp4 THEN 
                is_c1_libCM := ChiefMaster0_IN_Default_l;
                REQ_HV_ON := 0.0;
                ContactorState := 1.0;
            END_IF;
            IF temp3 THEN 
                is_c1_libCM := ChiefMaster0_IN_CONTACTOR_ON;
                REQ_HV_ON := 1.0;
                ContactorState := 3.0;
            END_IF;
            IF temp2 THEN 
                REQ_HV_ON := 0.0;
                ContactorState := 2.0;
            END_IF;
        END_IF;
END_CASE;

