            is_c21_ChiefMaster0 := ChiefMaster0_IN_Default;
            Precharge_Satus := 0.0;
        ELSE 
            CASE is_c21_ChiefMaster0 OF
                ChiefMaster0_IN_Default: 
                    IF REQ_MainHV_ON_Precharge AND ( NOT KL15_CM_diable) THEN 
                        is_c21_ChiefMaster0 := ChiefMaster0_IN_delay1;
                        temporalCounter_i1(timerAction := 1, maxTime := 0);
                        temporalCounter_i2(timerAction := 1, maxTime := 0);
