                        Precharge_Satus := 0.0;
                    ELSE 
                        Precharge_Satus := 2.0;
                    END_IF;
                ChiefMaster0_IN_PrechargeSuccess: 
                    IF (MainHV_Minus_Status = 1.0) OR (MainHV_Minus_Status = 3.0) THEN 
                        is_c21_ChiefMaster0 := ChiefMaster0_IN_Default;
