                    IF temporalCounter_i2.done THEN 
                        IF  NOT LoadCurrent THEN 
                            IF ABS(LoadVoltage - SystemVoltage) <= 5.0 THEN 
                                is_c21_ChiefMaster0 := ChiefMaster0_IN_PrechargeSuccess;
                                Precharge_Satus := 1.0;
                            ELSE 
                                temp1 := TRUE;
                            END_IF;
                        ELSE 
                            temp1 := TRUE;
                        END_IF;
                    ELSE 
                        temp1 := TRUE;
                    END_IF;
                    temporalCounter_i1(timerAction := 2, maxTime := 3000);
                    IF temp1 AND temporalCounter_i1.done THEN 
                        is_c21_ChiefMaster0 := ChiefMaster0_IN_PrechargeFail;
                        Precharge_Satus := 2.0;
                    END_IF;
            END_CASE;
        END_IF;
END_CASE;

