                            MainHV_Minus_Status := 3.0;
                        ELSE 
                            MainHV_Minus_Status := 2.0;
                        END_IF;
                    END_IF;
                b_ChiefMaster0_IN_hold: 
                    IF  NOT MainHV_ON_Minus_FB THEN 
                        is_c40_libCM := ChiefMaster0_IN_open;
                        MainHV_Minus_Status := 1.0;
                    ELSE 
                        temporalCounter_i1(timerAction := 2, maxTime := TRUNC(REAL_TO_LREAL(DelayTime_s) * 1000.0));
                        IF temporalCounter_i1.done THEN 
                            is_c40_libCM := ChiefMaster0_IN_Error;
                            MainHV_Minus_Status := 3.0;
                        ELSE 
