                    END_IF;
                ELSE
                    IF REQ_MainHV_ON_MINUS THEN 
                        is_c40_libCM := ChiefMaster0_IN_hold1;
                        temporalCounter_i1(timerAction := 1, maxTime := 0);
                        MainHV_Minus_Status := 1.0;
