CASE ssMethodType OF
    SS_INITIALIZE: 
        is_CHARGE := ChiefMaster0_IN_NO_ACTIVE_CHILD_j;
        is_DRIVE := ChiefMaster0_IN_NO_ACTIVE_CHILD_j;
        is_active_c7_libCM := 0;
        is_c7_libCM := ChiefMaster0_IN_NO_ACTIVE_CHILD_j;
        REQ_IMD_ON := FALSE;
        IMD_State := 0;
    SS_OUTPUT: 
        IF is_active_c7_libCM = 0 THEN 
            is_active_c7_libCM := 1;
            is_c7_libCM := ChiefMaster0_IN_Default_lr;
            REQ_IMD_ON := FALSE;
            IMD_State := 0;
        ELSE 
            CASE is_c7_libCM OF
                ChiefMaster0_IN_CHARGE: 
                    IF (((( NOT ChargeMode) OR DriveMode) OR SDError_BB) OR (BoxAvailable = 0.0)) AND ( NOT HV_REL_ON_BB) THEN 
                        is_CHARGE := ChiefMaster0_IN_NO_ACTIVE_CHILD_j;
                        is_c7_libCM := ChiefMaster0_IN_Default_lr;
                        REQ_IMD_ON := FALSE;
                        IMD_State := 0;
                    ELSE 
                        CASE is_CHARGE OF
                            ChiefMaster0_IN_CHARGE: 
                                IF (InsulationReadyOK AND (MinVtgBB = BattNo)) AND ( NOT HV_ON_BB) THEN 
                                    is_CHARGE := ChiefMaster0_IN_IMD_ON;
                                    REQ_IMD_ON := TRUE;
                                    IMD_State := 5;
                                ELSE 
                                    IF (InsulationReadyOK AND (MinVtgBB <> BattNo)) OR HV_ON_BB THEN 
                                        is_CHARGE := ChiefMaster0_IN_IMD_OFF;
                                        REQ_IMD_ON := FALSE;
                                        IMD_State := 6;
                                    ELSE 
                                        REQ_IMD_ON := TRUE;
                                        IMD_State := 4;
                                    END_IF;
                                END_IF;
                            ChiefMaster0_IN_IMD_OFF: 
                                IF ((((MinVtgBB = BattNo) AND ( NOT IMD_Active_BB1)) AND ( NOT IMD_Active_BB2)) AND ( NOT IMD_Active_BB3)) AND IsolationMeasurementRequest THEN 
                                    is_CHARGE := ChiefMaster0_IN_IMD_ON;
                                    REQ_IMD_ON := TRUE;
                                    IMD_State := 5;
                                ELSE 
                                    REQ_IMD_ON := FALSE;
                                    IMD_State := 6;
                                END_IF;
                            ELSE
                                IF HV_ON_BB AND ( NOT IsolationMeasurementRequest) THEN 
                                    is_CHARGE := ChiefMaster0_IN_IMD_OFF;
                                    REQ_IMD_ON := FALSE;
                                    IMD_State := 6;
                                ELSE 
                                    REQ_IMD_ON := TRUE;
                                    IMD_State := 5;
                                END_IF;
                        END_CASE;
                    END_IF;
                ChiefMaster0_IN_DRIVE: 
                    IF (((( NOT DriveMode) OR ChargeMode) OR SDError_BB) OR (BoxAvailable = 0.0)) AND ( NOT HV_REL_ON_BB) THEN 
                        is_DRIVE := ChiefMaster0_IN_NO_ACTIVE_CHILD_j;
                        is_c7_libCM := ChiefMaster0_IN_Default_lr;
                        REQ_IMD_ON := FALSE;
                        IMD_State := 0;
                    ELSE 
                        CASE is_DRIVE OF
                            ChiefMaster0_IN_DRIVE_n: 
                                IF (InsulationReadyOK AND (MaxVtgBB = BattNo)) AND ( NOT HV_ON_BB) THEN 
                                    is_DRIVE := ChiefMaster0_IN_IMD_ON;
                                    REQ_IMD_ON := TRUE;
                                    IMD_State := 2;
                                ELSE 
                                    IF (InsulationReadyOK AND (MaxVtgBB <> BattNo)) OR HV_ON_BB THEN 
                                        is_DRIVE := ChiefMaster0_IN_IMD_OFF;
                                        REQ_IMD_ON := FALSE;
                                        IMD_State := 3;
                                    ELSE 
                                        REQ_IMD_ON := TRUE;
                                        IMD_State := 1;
                                    END_IF;
                                END_IF;
                            ChiefMaster0_IN_IMD_OFF: 
                                IF ((((MaxVtgBB = BattNo) AND ( NOT IMD_Active_BB1)) AND ( NOT IMD_Active_BB2)) AND ( NOT IMD_Active_BB3)) AND IsolationMeasurementRequest THEN 
                                    is_DRIVE := ChiefMaster0_IN_IMD_ON;
                                    REQ_IMD_ON := TRUE;
                                    IMD_State := 2;
                                ELSE 
                                    REQ_IMD_ON := FALSE;
                                    IMD_State := 3;
                                END_IF;
                            ELSE
                                IF HV_ON_BB AND ( NOT IsolationMeasurementRequest) THEN 
                                    is_DRIVE := ChiefMaster0_IN_IMD_OFF;
                                    REQ_IMD_ON := FALSE;
                                    IMD_State := 3;
                                ELSE 
                                    REQ_IMD_ON := TRUE;
                                    IMD_State := 2;
                                END_IF;
                        END_CASE;
                    END_IF;
                ELSE
                    tmp :=  NOT SDError_BB;
                    IF ((ChargeMode AND ( NOT DriveMode)) AND tmp) AND (BoxAvailable = 1.0) THEN 
                        is_c7_libCM := ChiefMaster0_IN_CHARGE;
                        is_CHARGE := ChiefMaster0_IN_CHARGE;
                        REQ_IMD_ON := TRUE;
                        IMD_State := 4;
                    ELSE 
                        IF ((DriveMode AND ( NOT ChargeMode)) AND tmp) AND (BoxAvailable = 1.0) THEN 
                            is_c7_libCM := ChiefMaster0_IN_DRIVE;
                            is_DRIVE := ChiefMaster0_IN_DRIVE_n;
                            REQ_IMD_ON := TRUE;
                            IMD_State := 1;
                        ELSE 
                            REQ_IMD_ON := FALSE;
                            IMD_State := 0;
                        END_IF;
                    END_IF;
            END_CASE;
        END_IF;
END_CASE;

CASE ssMethodType OF
    SS_INITIALIZE: 
        temporalCounter_i1(timerAction := 1, maxTime := 0);
        is_active_c3_libCM := 0;
        is_c3_libCM := ChiefMaster0_IN_NO_ACTIVE_CHILD_d;
        Out := FALSE;
    SS_OUTPUT: 
        IF is_active_c3_libCM = 0 THEN 
            is_active_c3_libCM := 1;
            is_c3_libCM := ChiefMaster0_IN_Default_p;
            Out := FALSE;
        ELSE 
            CASE is_c3_libCM OF
                ChiefMaster0_IN_Actual: 
                    IF  NOT In THEN 
                        is_c3_libCM := ChiefMaster0_IN_Default_p;
                        Out := FALSE;
                    ELSE 
                        Out := TRUE;
                    END_IF;
                ChiefMaster0_IN_Default_p: 
                    IF In THEN 
                        is_c3_libCM := ChiefMaster0_IN_Hold_a;
                        temporalCounter_i1(timerAction := 1, maxTime := 0);
                        Out := FALSE;
                    ELSE 
                        Out := FALSE;
                    END_IF;
                ELSE
                    temporalCounter_i1(timerAction := 2, maxTime := 1000);
                    IF temporalCounter_i1.done THEN 
                        is_c3_libCM := ChiefMaster0_IN_Actual;
                        Out := In;
                    ELSE 
                        IF  NOT In THEN 
                            is_c3_libCM := ChiefMaster0_IN_Default_p;
                            Out := FALSE;
                        ELSE 
                            Out := FALSE;
                        END_IF;
                    END_IF;
            END_CASE;
        END_IF;
END_CASE;

