CASE ssMethodType OF
    SS_INITIALIZE: 
        temporalCounter_i1(timerAction := 1, maxTime := 0);
        is_active_c13_libCM := 0;
        is_c13_libCM := ChiefMaster0_IN_NO_ACTIVE_CHILD_eq;
        SW_Reset := FALSE;
    SS_OUTPUT: 
        IF is_active_c13_libCM = 0 THEN 
            is_active_c13_libCM := 1;
            is_c13_libCM := ChiefMaster0_IN_Default_f;
            SW_Reset := FALSE;
        ELSE 
            CASE is_c13_libCM OF
                ChiefMaster0_IN_Default_f: 
                    IF Error THEN 
                        is_c13_libCM := ChiefMaster0_IN_hold_o;
                        temporalCounter_i1(timerAction := 1, maxTime := 0);
                        SW_Reset := FALSE;
                    ELSE 
                        SW_Reset := FALSE;
                    END_IF;
                ChiefMaster0_IN_Delay_h: 
                    temporalCounter_i1(timerAction := 2, maxTime := 10);
                    IF temporalCounter_i1.done THEN 
                        is_c13_libCM := ChiefMaster0_IN_pulse_n;
                        SW_Reset := FALSE;
                    ELSE 
                        SW_Reset := TRUE;
                    END_IF;
                ChiefMaster0_IN_KL15_reset: 
                    temporalCounter_i1(timerAction := 2, maxTime := 25000);
                    IF temporalCounter_i1.done THEN 
                        IF  NOT Error THEN 
                            is_c13_libCM := ChiefMaster0_IN_Default_f;
                            SW_Reset := FALSE;
                        ELSE 
                            SW_Reset := FALSE;
                        END_IF;
                    ELSE 
                        SW_Reset := FALSE;
                    END_IF;
                ChiefMaster0_IN_hold_o: 
                    temporalCounter_i1(timerAction := 2, maxTime := 5000);
                    IF temporalCounter_i1.done THEN 
                        is_c13_libCM := ChiefMaster0_IN_Delay_h;
                        temporalCounter_i1(timerAction := 1, maxTime := 0);
                        SW_Reset := TRUE;
                    ELSE 
                        IF  NOT Error THEN 
                            is_c13_libCM := ChiefMaster0_IN_Default_f;
                            SW_Reset := FALSE;
                        ELSE 
                            SW_Reset := FALSE;
                        END_IF;
                    END_IF;
                ELSE
                    IF KL15_reset THEN 
                        is_c13_libCM := ChiefMaster0_IN_KL15_reset;
                        temporalCounter_i1(timerAction := 1, maxTime := 0);
                        SW_Reset := FALSE;
                    ELSE 
                        SW_Reset := FALSE;
                    END_IF;
            END_CASE;
        END_IF;
