            Count := 0.0;
        ELSE 
            CASE is_c14_libCM OF
                ChiefMaster0_IN_Default_g: 
                    IF SW_Reset THEN 
                        is_c14_libCM := ChiefMaster0_IN_Delay_b;
                        Count := Count + 1.0;
                    ELSE 
                        Count := 0.0;
                    END_IF;
                ChiefMaster0_IN_Delay_b: 
                    IF  NOT SW_Reset THEN 
                        is_c14_libCM := ChiefMaster0_IN_Delay1_i;
                    ELSE 
                        Count := Count + 1.0;
                    END_IF;
                ELSE
                    IF KL_15_reset_CM THEN 
                        is_c14_libCM := ChiefMaster0_IN_Default_g;
                        Count := 0.0;
