CASE ssMethodType OF
    SS_INITIALIZE: 
        is_OFF := ChiefMaster0_IN_NO_ACTIVE_CHILD_k;
        is_ON := ChiefMaster0_IN_NO_ACTIVE_CHILD_k;
        is_active_c27_ChiefMaster0 := 0;
        is_c27_ChiefMaster0 := ChiefMaster0_IN_NO_ACTIVE_CHILD_k;
        FL_u8SS_ChiefMaster_State := 0;
    SS_OUTPUT: 
        IF is_active_c27_ChiefMaster0 = 0 THEN 
            is_active_c27_ChiefMaster0 := 1;
            is_c27_ChiefMaster0 := ChiefMaster0_IN_Sleep;
            FL_u8SS_ChiefMaster_State := 0;
        ELSE 
            CASE is_c27_ChiefMaster0 OF
                ChiefMaster0_IN_Error_o: 
                    tmp :=  NOT ShutdownError;
                    IF tmp AND KL15 THEN 
                        is_c27_ChiefMaster0 := ChiefMaster0_IN_ON;
                        is_ON := ChiefMaster0_IN_KL15ON;
                        FL_u8SS_ChiefMaster_State := 1;
                    ELSE 
                        IF tmp AND ( NOT KL15) THEN 
                            is_c27_ChiefMaster0 := ChiefMaster0_IN_OFF;
                            is_OFF := ChiefMaster0_IN_BDURelayOpen_Req;
                            FL_u8SS_ChiefMaster_State := 8;
                        ELSE 
                            FL_u8SS_ChiefMaster_State := 14;
                        END_IF;
                    END_IF;
                ChiefMaster0_IN_OFF: 
                    IF FL_u8SS_ChiefMaster_State = 13 THEN 
                        is_OFF := ChiefMaster0_IN_NO_ACTIVE_CHILD_k;
                        is_c27_ChiefMaster0 := ChiefMaster0_IN_Sleep;
                        FL_u8SS_ChiefMaster_State := 0;
                    ELSE 
                        IF ShutdownError THEN 
                            is_OFF := ChiefMaster0_IN_NO_ACTIVE_CHILD_k;
                            is_c27_ChiefMaster0 := ChiefMaster0_IN_Error_o;
                            FL_u8SS_ChiefMaster_State := 14;
                        ELSE 
                            CASE is_OFF OF
                                ChiefMaster0_IN_BDURelayOpen: 
                                    IF  NOT BattRelay_Close_Req THEN 
                                        is_OFF := ChiefMaster0_IN_BattRelayOpen_Req;
                                        FL_u8SS_ChiefMaster_State := 10;
                                    ELSE 
                                        FL_u8SS_ChiefMaster_State := 9;
                                    END_IF;
                                ChiefMaster0_IN_BDURelayOpen_Req: 
                                    IF MainHV_Plus_Status = 0.0 THEN 
                                        is_OFF := ChiefMaster0_IN_BDURelayOpen;
                                        FL_u8SS_ChiefMaster_State := 9;
                                    ELSE 
                                        FL_u8SS_ChiefMaster_State := 8;
                                    END_IF;
                                ChiefMaster0_IN_BattRelayOpen: 
                                    IF  NOT REQ_IMD_ON THEN 
                                        is_OFF := ChiefMaster0_IN_ISOMonitorOFF;
                                        FL_u8SS_ChiefMaster_State := 12;
                                    ELSE 
                                        FL_u8SS_ChiefMaster_State := 11;
                                    END_IF;
                                ChiefMaster0_IN_BattRelayOpen_Req: 
                                    IF  NOT BattRelay_Closed THEN 
                                        is_OFF := ChiefMaster0_IN_BattRelayOpen;
                                        FL_u8SS_ChiefMaster_State := 11;
                                    ELSE 
                                        FL_u8SS_ChiefMaster_State := 10;
                                    END_IF;
                                ChiefMaster0_IN_ISOMonitorOFF: 
                                    IF  NOT KL15_AllBoxes THEN 
                                        is_OFF := ChiefMaster0_IN_KL15OFF;
                                        FL_u8SS_ChiefMaster_State := 13;
                                    ELSE 
                                        FL_u8SS_ChiefMaster_State := 12;
                                    END_IF;
                                ELSE
                                    FL_u8SS_ChiefMaster_State := 13;
                            END_CASE;
                        END_IF;
                    END_IF;
                ChiefMaster0_IN_ON: 
                    IF  NOT KL15 THEN 
                        is_ON := ChiefMaster0_IN_NO_ACTIVE_CHILD_k;
                        is_c27_ChiefMaster0 := ChiefMaster0_IN_OFF;
                        is_OFF := ChiefMaster0_IN_BDURelayOpen_Req;
                        FL_u8SS_ChiefMaster_State := 8;
                    ELSE 
                        IF ShutdownError THEN 
                            is_ON := ChiefMaster0_IN_NO_ACTIVE_CHILD_k;
                            is_c27_ChiefMaster0 := ChiefMaster0_IN_Error_o;
                            FL_u8SS_ChiefMaster_State := 14;
                        ELSE 
                            CASE is_ON OF
                                ChiefMaster0_IN_BDURelayClose: 
                                    FL_u8SS_ChiefMaster_State := 7;
                                ChiefMaster0_IN_BDURelayClose_Req: 
                                    IF MainHV_Plus_Status = 2.0 THEN 
                                        is_ON := ChiefMaster0_IN_BDURelayClose;
                                        FL_u8SS_ChiefMaster_State := 7;
                                    ELSE 
                                        FL_u8SS_ChiefMaster_State := 6;
                                    END_IF;
                                ChiefMaster0_IN_BattRelayClose: 
                                    IF FL_boREQ_MainHV_ON_MINUS THEN 
                                        is_ON := ChiefMaster0_IN_BDURelayClose_Req;
                                        FL_u8SS_ChiefMaster_State := 6;
                                    ELSE 
                                        IF  NOT BattRelay_Closed THEN 
                                            is_ON := ChiefMaster0_IN_BattRelayClose_Req;
                                            FL_u8SS_ChiefMaster_State := 4;
                                        ELSE 
                                            FL_u8SS_ChiefMaster_State := 5;
                                        END_IF;
                                    END_IF;
                                ChiefMaster0_IN_BattRelayClose_Req: 
                                    IF BattRelay_Closed THEN 
                                        is_ON := ChiefMaster0_IN_BattRelayClose;
                                        FL_u8SS_ChiefMaster_State := 5;
                                    ELSE 
                                        FL_u8SS_ChiefMaster_State := 4;
                                    END_IF;
                                ChiefMaster0_IN_ISOMonitor_OK: 
                                    IF BattRelay_Close_Req THEN 
                                        is_ON := ChiefMaster0_IN_BattRelayClose_Req;
                                        FL_u8SS_ChiefMaster_State := 4;
                                    ELSE 
                                        FL_u8SS_ChiefMaster_State := 3;
                                    END_IF;
                                ChiefMaster0_IN_ISOMonitor_check: 
                                    IF InsulationReadyOK THEN 
                                        is_ON := ChiefMaster0_IN_ISOMonitor_OK;
                                        FL_u8SS_ChiefMaster_State := 3;
                                    ELSE 
                                        FL_u8SS_ChiefMaster_State := 2;
                                    END_IF;
                                ELSE
                                    IF KL15_AllBoxes AND IMD_Available THEN 
                                        is_ON := ChiefMaster0_IN_ISOMonitor_check;
                                        FL_u8SS_ChiefMaster_State := 2;
                                    ELSE 
                                        FL_u8SS_ChiefMaster_State := 1;
                                    END_IF;
                            END_CASE;
                        END_IF;
                    END_IF;
                ELSE
                    IF KL15 THEN 
                        is_c27_ChiefMaster0 := ChiefMaster0_IN_ON;
                        is_ON := ChiefMaster0_IN_KL15ON;
                        FL_u8SS_ChiefMaster_State := 1;
                    ELSE 
                        FL_u8SS_ChiefMaster_State := 0;
                    END_IF;
            END_CASE;
        END_IF;
END_CASE;

CASE ssMethodType OF
    SS_INITIALIZE: 
        i0_EMSRET(ssMethodType := SS_INITIALIZE, AllOK := rtb_FL_boSS_EMSRET_POWER, b_Reset := b_Reset);
        FL_boSS_EMSRET_POWER := i0_EMSRET.EMSRET_mb;
    SS_OUTPUT: 
        i0_EMSRET(ssMethodType := SS_OUTPUT, AllOK := ( NOT ESD) AND ( NOT HVILNOK), b_Reset := b_Reset);
        FL_boSS_EMSRET_POWER := i0_EMSRET.EMSRET_mb;
END_CASE;

CASE ssMethodType OF
    SS_INITIALIZE: 
        temporalCounter_i1(timerAction := 1, maxTime := 0);
        is_active_c50_ChiefMaster0 := 0;
        is_c50_ChiefMaster0 := ChiefMaster0_IN_NO_ACTIVE_CHILD_jr;
        EMSRET_mb := FALSE;
    SS_OUTPUT: 
        IF is_active_c50_ChiefMaster0 = 0 THEN 
            is_active_c50_ChiefMaster0 := 1;
            is_c50_ChiefMaster0 := ChiefMaster0_IN_OFF_i;
            EMSRET_mb := FALSE;
        ELSE 
            CASE is_c50_ChiefMaster0 OF
                ChiefMaster0_IN_Delay_bi: 
                    temporalCounter_i1(timerAction := 2, maxTime := 3000);
                    IF temporalCounter_i1.done THEN 
                        is_c50_ChiefMaster0 := ChiefMaster0_IN_ShutOff;
                        EMSRET_mb := FALSE;
                    ELSE 
                        EMSRET_mb := TRUE;
                    END_IF;
                ChiefMaster0_IN_OFF_i: 
                    IF AllOK THEN 
                        is_c50_ChiefMaster0 := ChiefMaster0_IN_ON_g;
                        EMSRET_mb := TRUE;
                    ELSE 
                        EMSRET_mb := FALSE;
                    END_IF;
                ChiefMaster0_IN_ON_g: 
                    IF  NOT AllOK THEN 
                        is_c50_ChiefMaster0 := ChiefMaster0_IN_Delay_bi;
                        temporalCounter_i1(timerAction := 1, maxTime := 0);
                        EMSRET_mb := TRUE;
                    ELSE 
                        EMSRET_mb := TRUE;
                    END_IF;
                ELSE
                    IF b_Reset THEN 
                        is_c50_ChiefMaster0 := ChiefMaster0_IN_OFF_i;
                        EMSRET_mb := FALSE;
                    ELSE 
                        EMSRET_mb := FALSE;
                    END_IF;
            END_CASE;
        END_IF;
END_CASE;

CASE ssMethodType OF
    SS_INITIALIZE: 
        temporalCounter_i1(timerAction := 1, maxTime := 0);
        is_active_c59_ChiefMaster0 := 0;
        is_c59_ChiefMaster0 := ChiefMaster0_IN_NO_ACTIVE_CHILD_jg;
        out := FALSE;
    SS_OUTPUT: 
        IF is_active_c59_ChiefMaster0 = 0 THEN 
            is_active_c59_ChiefMaster0 := 1;
            is_c59_ChiefMaster0 := ChiefMaster0_IN_Initial1;
            temporalCounter_i1(timerAction := 1, maxTime := 0);
            out := FALSE;
        ELSE 
            CASE is_c59_ChiefMaster0 OF
                ChiefMaster0_IN_After_delay1: 
                    out := In;
                ELSE
                    temporalCounter_i1(timerAction := 2, maxTime := 7000);
                    IF temporalCounter_i1.done THEN 
                        is_c59_ChiefMaster0 := ChiefMaster0_IN_After_delay1;
                        out := In;
                    ELSE 
                        out := FALSE;
                    END_IF;
            END_CASE;
        END_IF;
END_CASE;

CASE ssMethodType OF
    SS_INITIALIZE: 
        is_active_c1_Library_DataProcessing_v1_1 := 0;
        is_c1_Library_DataProcessing_v1_1 := ChiefMaster0_IN_NO_ACTIVE_CHILD_p;
        boOutput := FALSE;
    SS_OUTPUT: 
        IF is_active_c1_Library_DataProcessing_v1_1 = 0 THEN 
            is_active_c1_Library_DataProcessing_v1_1 := 1;
            is_c1_Library_DataProcessing_v1_1 := ChiefMaster0_IN_OFF_c;
            boOutput := boInitial_Value;
        ELSE 
            CASE is_c1_Library_DataProcessing_v1_1 OF
                ChiefMaster0_IN_HighValue: 
                    IF sSignal < sLB THEN 
                        is_c1_Library_DataProcessing_v1_1 := ChiefMaster0_IN_LowValue;
                        boOutput := boValue_Deactivated;
                    END_IF;
                ChiefMaster0_IN_LowValue: 
                    IF sSignal > b_sUB THEN 
                        is_c1_Library_DataProcessing_v1_1 := ChiefMaster0_IN_HighValue;
                        boOutput := boValue_Activated;
                    END_IF;
                ELSE
                    IF sSignal < sLB THEN 
                        is_c1_Library_DataProcessing_v1_1 := ChiefMaster0_IN_LowValue;
                        boOutput := boValue_Deactivated;
                    ELSE 
                        IF sSignal > b_sUB THEN 
                            is_c1_Library_DataProcessing_v1_1 := ChiefMaster0_IN_HighValue;
                            boOutput := boValue_Activated;
                        END_IF;
                    END_IF;
            END_CASE;
        END_IF;
END_CASE;

CASE ssMethodType OF
    SS_INITIALIZE: 
        temporalCounter_i1(timerAction := 1, maxTime := 0);
        is_active_c56_ChiefMaster0 := 0;
        is_c56_ChiefMaster0 := ChiefMaster0_IN_NO_ACTIVE_CHILD_cr;
        out := FALSE;
    SS_OUTPUT: 
        IF is_active_c56_ChiefMaster0 = 0 THEN 
            is_active_c56_ChiefMaster0 := 1;
            is_c56_ChiefMaster0 := ChiefMaster0_IN_Initial_h;
            out := HVIL_IN;
        ELSE 
            CASE is_c56_ChiefMaster0 OF
                ChiefMaster0_IN_After_delay_c: 
                    IF  NOT HVIL_IN THEN 
                        is_c56_ChiefMaster0 := ChiefMaster0_IN_Initial_h;
                        out := FALSE;
                    ELSE 
                        out := TRUE;
                    END_IF;
                ChiefMaster0_IN_Delay_k: 
                    temporalCounter_i1(timerAction := 2, maxTime := USINT_TO_DINT(IP_HVIL_Delay_ms));
                    IF temporalCounter_i1.done THEN 
                        is_c56_ChiefMaster0 := ChiefMaster0_IN_After_delay_c;
                        out := HVIL_IN;
                    ELSE 
                        out := TRUE;
                    END_IF;
                ELSE
                    IF  NOT HVIL_IN THEN 
                        is_c56_ChiefMaster0 := ChiefMaster0_IN_Delay_k;
                        temporalCounter_i1(timerAction := 1, maxTime := 0);
                        out := TRUE;
                    ELSE 
                        out := TRUE;
                    END_IF;
            END_CASE;
        END_IF;
END_CASE;

CASE ssMethodType OF
    SS_INITIALIZE: 
        is_active_c4_Library_DataProcessing_v1_1 := 0;
        is_c4_Library_DataProcessing_v1_1 := ChiefMaster0_IN_NO_ACTIVE_CHILD_i2;
        boOutput := FALSE;
    SS_OUTPUT: 
        IF is_active_c4_Library_DataProcessing_v1_1 = 0 THEN 
            is_active_c4_Library_DataProcessing_v1_1 := 1;
            is_c4_Library_DataProcessing_v1_1 := ChiefMaster0_IN_OFF_o;
            boOutput := boInitial_Value;
        ELSE 
            CASE is_c4_Library_DataProcessing_v1_1 OF
                ChiefMaster0_IN_HighValue_a: 
                    IF sSignal > b_sUB THEN 
                        is_c4_Library_DataProcessing_v1_1 := ChiefMaster0_IN_LowValue_n;
                        boOutput := boValue_Deactivated;
                    END_IF;
                ChiefMaster0_IN_LowValue_n: 
                    IF sSignal < sLB THEN 
                        is_c4_Library_DataProcessing_v1_1 := ChiefMaster0_IN_HighValue_a;
                        boOutput := boValue_Activated;
                    END_IF;
                ELSE
                    IF sSignal > b_sUB THEN 
                        is_c4_Library_DataProcessing_v1_1 := ChiefMaster0_IN_LowValue_n;
                        boOutput := boValue_Deactivated;
                    ELSE 
                        IF sSignal < sLB THEN 
                            is_c4_Library_DataProcessing_v1_1 := ChiefMaster0_IN_HighValue_a;
                            boOutput := boValue_Activated;
                        END_IF;
                    END_IF;
            END_CASE;
        END_IF;
END_CASE;

IF IMD_Active_BB1 THEN 
    FL_sCalculated_Vtg_Diff_BB3 := FL_sVtgExt_BB1;
ELSIF IMD_Active_BB2 THEN 
    FL_sCalculated_Vtg_Diff_BB3 := FL_sVtgExt_BB2;
ELSIF IMD_Active_BB3 THEN 
    FL_sCalculated_Vtg_Diff_BB3 := FL_sVtgExt_BB3;
ELSE 
    IF HV_REL_ON_BB1 THEN 
        temp1 := FL_sVtgExt_BB1;
    ELSE 
        temp1 := 0.0;
    END_IF;
    IF HV_REL_ON_BB2 THEN 
        temp2 := FL_sVtgExt_BB2;
    ELSE 
        temp2 := 0.0;
    END_IF;
    IF HV_REL_ON_BB3 THEN 
        temp3 := FL_sVtgExt_BB3;
    ELSE 
        temp3 := 0.0;
    END_IF;
    temp6 := MAX(temp1, temp2);
    FL_sCalculated_Vtg_Diff_BB3 := MAX(temp6, temp3);
END_IF;
FL_sCalculated_Vtg_Diff_BB1 := ABS(VtgInt_BB1 - FL_sCalculated_Vtg_Diff_BB3);
FL_sCalculated_Vtg_Diff_BB2 := ABS(VtgInt_BB2 - FL_sCalculated_Vtg_Diff_BB3);
FL_sCalculated_Vtg_Diff_BB3 := VtgInt_BB3 - FL_sCalculated_Vtg_Diff_BB3;
FL_sCalculated_Vtg_Diff_BB3 := ABS(FL_sCalculated_Vtg_Diff_BB3);
IF HV_REL_ON_BB2 THEN 
    FL_sCalculated_InrushCurrent_BB3 := InternalResistance_BB2;
ELSE 
    FL_sCalculated_InrushCurrent_BB3 := 0.0;
END_IF;
IF HV_REL_ON_BB3 THEN 
    FL_sCalculated_InrushCurrent_BB2 := InternalResistance_BB3;
ELSE 
    FL_sCalculated_InrushCurrent_BB2 := 0.0;
END_IF;
IF HV_REL_ON_BB1 THEN 
    FL_sCalculated_InrushCurrent_BB1 := InternalResistance_BB1;
ELSE 
    FL_sCalculated_InrushCurrent_BB1 := 0.0;
END_IF;
rtb_Add1_h := (FL_sCalculated_InrushCurrent_BB1 + FL_sCalculated_InrushCurrent_BB2) + InternalResistance_BB2;
rtb_Add2_a := (FL_sCalculated_InrushCurrent_BB3 + FL_sCalculated_InrushCurrent_BB1) + InternalResistance_BB3;
FL_sCalculated_InrushCurrent_BB1 := FL_sCalculated_Vtg_Diff_BB1 / (((FL_sCalculated_InrushCurrent_BB3 + FL_sCalculated_InrushCurrent_BB2) + InternalResistance_BB1) + FL_sInrushCurrent_dividebyzero);
FL_sCalculated_InrushCurrent_BB2 := FL_sCalculated_Vtg_Diff_BB2 / (rtb_Add1_h + FL_sInrushCurrent_dividebyzero);
FL_sCalculated_InrushCurrent_BB3 := FL_sCalculated_Vtg_Diff_BB3 / (rtb_Add2_a + FL_sInrushCurrent_dividebyzero);
FL_boSafeToCloseHV_BB3 := (HV_REL_ON_BB1 OR HV_REL_ON_BB2) OR HV_REL_ON_BB3;
FL_boSafeToCloseHV_BB1 := (FL_sCalculated_Vtg_Diff_BB1 < SafeVoltageToCloseHV_V) OR ((FL_sCalculated_InrushCurrent_BB1 < SafeCurrentToCloseHV_A) AND FL_boSafeToCloseHV_BB3);
FL_boSafeToCloseHV_BB2 := (FL_sCalculated_Vtg_Diff_BB2 < SafeVoltageToCloseHV_V) OR ((FL_sCalculated_InrushCurrent_BB2 < SafeCurrentToCloseHV_A) AND FL_boSafeToCloseHV_BB3);
FL_boSafeToCloseHV_BB3 := (FL_sCalculated_Vtg_Diff_BB3 < SafeVoltageToCloseHV_V) OR ((FL_sCalculated_InrushCurrent_BB3 < SafeCurrentToCloseHV_A) AND FL_boSafeToCloseHV_BB3);

rtb_AND7 := ( NOT IP_boBMS_SDError_BB1) AND (IP_boBMS_Batt1_Availability <> 0.0);
IF rtb_AND7 THEN 
    rtb_Switch4_o := REAL_TO_LREAL(IP_sBMS_VtgInt_BB1);
ELSE 
    rtb_Switch4_o := 0.0;
END_IF;
rtb_AND8 := ( NOT IP_boBMS_SDError_BB2) AND (IP_boBMS_Batt2_Availability <> 0.0);
IF rtb_AND8 THEN 
    rtb_Switch5_d := REAL_TO_LREAL(IP_sBMS_VtgInt_BB2);
ELSE 
    rtb_Switch5_d := 0.0;
END_IF;
rtb_AND9 := ( NOT IP_boBMS_SDError_BB3) AND (IP_boBMS_Batt3_Availability <> 0.0);
IF rtb_AND9 THEN 
    rtb_Switch6 := REAL_TO_LREAL(IP_sBMS_VtgInt_BB3);
ELSE 
    rtb_Switch6 := 0.0;
END_IF;
IF (IP_sBMS_VtgInt_BB1 > 10.0) AND rtb_AND7 THEN 
    rtb_Switch7 := IP_sBMS_VtgInt_BB1;
ELSE 
    rtb_Switch7 := UINT_TO_REAL(Voltage_NA_UB);
END_IF;
IF (IP_sBMS_VtgInt_BB2 > 10.0) AND rtb_AND8 THEN 
    rtb_Switch8 := IP_sBMS_VtgInt_BB2;
ELSE 
    rtb_Switch8 := UINT_TO_REAL(Voltage_NA_UB);
END_IF;
IF (IP_sBMS_VtgInt_BB3 > 10.0) AND rtb_AND9 THEN 
    rtb_Switch9 := IP_sBMS_VtgInt_BB3;
ELSE 
    rtb_Switch9 := UINT_TO_REAL(Voltage_NA_UB);
END_IF;
IF (rtb_Switch4_o >= rtb_Switch5_d) AND (rtb_Switch4_o >= rtb_Switch6) THEN 
    IT_u8BMS_BB_No_MaxVoltage := BattBox1_No;
ELSIF (rtb_Switch5_d >= rtb_Switch4_o) AND (rtb_Switch5_d >= rtb_Switch6) THEN 
    IT_u8BMS_BB_No_MaxVoltage := BattBox2_No;
ELSE 
    IT_u8BMS_BB_No_MaxVoltage := BattBox3_No;
END_IF;
IF (rtb_Switch7 <= rtb_Switch8) AND (rtb_Switch7 <= rtb_Switch9) THEN 
    IT_u8BMS_BB_No_MinVoltage := BattBox1_No;
ELSIF (rtb_Switch8 <= rtb_Switch7) AND (rtb_Switch8 <= rtb_Switch9) THEN 
    IT_u8BMS_BB_No_MinVoltage := BattBox2_No;
ELSE 
    IT_u8BMS_BB_No_MinVoltage := BattBox3_No;
END_IF;

IF in THEN 
    PLC_BOOL_TO_LREAL := 1.0;
ELSE 
    PLC_BOOL_TO_LREAL := 0.0;
END_IF;

CASE timerAction OF
    1:
        plcTimer(IN:=FALSE, PT:=T#0ms);
        plcTimerExpired := FALSE;
        done := FALSE;
    2:
        IF (NOT(plcTimerExpired)) THEN
            plcTimer(IN:=TRUE, PT:=DINT_TO_TIME(maxTime));
        END_IF;
        plcTimerExpired := plcTimer.Q;
        done := plcTimerExpired;
    3:
        IF (NOT(plcTimerExpired)) THEN
            plcTimer(IN:=TRUE, PT:=DINT_TO_TIME(maxTime));
        END_IF;
        plcTimerExpired := plcTimer.Q;
        done := NOT(plcTimerExpired);
END_CASE;
